request_examples.code:
curl -X POST "{{BASE_URL}}/v1/workflows/txt2img-basic/runs" \
  -H "Authorization: Bearer {{API_KEY}}" \
  -H "Content-Type: application/json" \
  -d '{
    "inputs": {
      "prompt": "a lighthouse on a cliff at sunset, oil painting",
      "seed": 42,
      "steps": 30
    },
    "idempotency_key": "order-20261016-0001"
  }'

const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";

const resp = await fetch(`${BASE_URL}/v1/workflows/txt2img-basic/runs`, {
  method: "POST",
  headers: {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    inputs: {
      prompt: "a lighthouse on a cliff at sunset, oil painting",
      seed: 42,
      steps: 30,
    },
    idempotency_key: "order-20261016-0001",
  }),
});
if (resp.status !== 202) throw new Error(JSON.stringify(await resp.json()));
const job = await resp.json();
console.log(job.job_id, job.status);

